from django.contrib import admin
from django.contrib.auth import views as auth_views
from django.urls import include, path
from tasks import views as task_views

urlpatterns = [path("admin/", admin.site.urls), path("login/", auth_views.LoginView.as_view(template_name="tasks/login.html"), name="login"), path("registro/", task_views.register, name="register"), path("invitado/", task_views.guest_login, name="guest_login"), path("recuperar-clave/", auth_views.PasswordResetView.as_view(template_name="tasks/password_reset_form.html", email_template_name="tasks/password_reset_email.txt", subject_template_name="tasks/password_reset_subject.txt"), name="recover_password"), path("recuperar-clave/enviado/", auth_views.PasswordResetDoneView.as_view(template_name="tasks/password_reset_done.html"), name="password_reset_done"), path("restablecer/<uidb64>/<token>/", auth_views.PasswordResetConfirmView.as_view(template_name="tasks/password_reset_confirm.html"), name="password_reset_confirm"), path("restablecer/listo/", auth_views.PasswordResetCompleteView.as_view(template_name="tasks/password_reset_complete.html"), name="password_reset_complete"), path("salir/", task_views.logout_view, name="logout"), path("", include("tasks.urls"))]
